/**
 * Executes the given supplier and fails the test if any exception is thrown.
 */
private static <T> T assertDoesNotThrow(ThrowingSupplier<T> supplier) {
    try {
        return supplier.get();
    } catch (Exception e) {
        fail("Unexpected exception: " + e);
        return null; // unreachable
    }
}

/**
 * Functional interface similar to {@link java.util.function.Supplier} but allows
 * throwing checked exceptions.
 */
@FunctionalInterface
private interface ThrowingSupplier<T> {
    T get() throws Exception;
}

