public void testClosedWriterThrowsOnFlush() throws IOException {
    JsonWriter writer = assertDoesNotThrow(
            () -> createClosedWriter(),
            "Unexpected exception during writer setup");
    IllegalStateException e = assertThrows(IllegalStateException.class, writer::flush);
    assertThat(e).hasMessageThat().isEqualTo("JsonWriter is closed.");
}

private JsonWriter createClosedWriter() throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter writer = new JsonWriter(stringWriter);
    writer.beginArray();
    writer.endArray();
    writer.close();
    return writer;
}

private static <T> T assertDoesNotThrow(Callable<T> callable, String message) {
    try {
        return callable.call();
    } catch (Exception e) {
        fail(message + ": " + e);
        return null; // Unreachable, but required for compilation
    }
}

