private static final int INITIAL_VALUE = 1;
private static final int UPDATED_VALUE = 2;
private static final int NEGATIVE_INDEX = -1;
private static final int VALID_INDEX = 0;
private static final int OUT_OF_BOUNDS_INDEX = 2;

@Test
public void testSet() {
    JsonArray a = new JsonArray();
    a.add(INITIAL_VALUE);

    List<JsonElement> list = a.asList();
    JsonElement old = list.set(VALID_INDEX, new JsonPrimitive(UPDATED_VALUE));

    assertWithMessage("Old element should be the original value")
        .that(old).isEqualTo(new JsonPrimitive(INITIAL_VALUE));
    assertWithMessage("Element at index 0 should be updated to the new value in the list view")
        .that(list.get(VALID_INDEX)).isEqualTo(new JsonPrimitive(UPDATED_VALUE));
    assertWithMessage("Underlying JsonArray should reflect the updated element at index 0")
        .that(a.get(VALID_INDEX)).isEqualTo(new JsonPrimitive(UPDATED_VALUE));

    assertThrows("Setting element at a negative index should throw IndexOutOfBoundsException",
            IndexOutOfBoundsException.class,
            () -> list.set(NEGATIVE_INDEX, new JsonPrimitive(INITIAL_VALUE)));
    assertThrows("Setting element beyond the list size should throw IndexOutOfBoundsException",
            IndexOutOfBoundsException.class,
            () -> list.set(OUT_OF_BOUNDS_INDEX, new JsonPrimitive(INITIAL_VALUE)));

    NullPointerException e = assertThrows("Setting a null element should throw NullPointerException",
            NullPointerException.class,
            () -> list.set(VALID_INDEX, null));
    assertWithMessage("Exception message should indicate that element must be non-null")
        .that(e).hasMessageThat().isEqualTo("Element must be non-null");
}

