void testMixedCaseBooleanLiterals() {
  Assertions.assertDoesNotThrow(() -> {
    JsonReader reader = new JsonReader(reader("[True,TruE,False,FALSE]"));
    reader.beginArray();

    assertThat(reader.nextBoolean())
        .named("First literal 'True' should be interpreted as true")
        .isTrue();

    assertThat(reader.nextBoolean())
        .named("Second literal 'TruE' should be interpreted as true")
        .isTrue();

    assertThat(reader.nextBoolean())
        .named("Third literal 'False' should be interpreted as false")
        .isFalse();

    assertThat(reader.nextBoolean())
        .named("Fourth literal 'FALSE' should be interpreted as false")
        .isFalse();

    reader.endArray();
    assertThat(reader.peek())
        .named("Reader should be at END_DOCUMENT after processing all literals")
        .isEqualTo(END_DOCUMENT);
  });
}

@Test
void testMixedCaseNullLiterals() {
  Assertions.assertDoesNotThrow(() -> {
    JsonReader reader = new JsonReader(reader("[NULL,nulL]"));
    reader.beginArray();

    reader.nextNull();
    // Add a descriptive check that the token after reading a null is indeed NULL
    assertThat(reader.peek())
        .named("Token after first null literal should be NULL")
        .isEqualTo(JsonToken.NULL);

    reader.nextNull();
    // Verify that the second null literal is also read correctly
    assertThat(reader.peek())
        .named("Token after second null literal should be NULL")
        .isEqualTo(JsonToken.NULL);

    reader.endArray();
    assertThat(reader.peek())
        .named("Reader should be at END_DOCUMENT after processing null literals")
        .isEqualTo(END_DOCUMENT);
  });
}

