/**
 * Parameterized test covering both positive and negative scenarios for {@link Element#hasClass(String)}.
 * Each row defines the class attribute value, the class to query, and the expected boolean result.
 */
@ParameterizedTest
@CsvSource({
    "'toto',               'toto',               true",
    "' toto',              'toto',               true",
    "'toto ',              'toto',               true",
    "'\toto ',             'toto',               true",
    "'  toto ',            'toto',               true",
    "'raulpismuth  ',      'raulpismuth',        true",
    "' abcd  raulpismuth efgh ', 'raulpismuth', true",
    "' abcd efgh raulpismuth',   'raulpismuth', true",
    "' abcd efgh raulpismuth ',  'raulpismuth', true",
    "'ab',                 'toto',               false",
    "'     ',              'toto',               false",
    "'tototo',             'toto',               false",
    "'someOther',          'raulpismuth',        false"
})
public void testHasClassDomMethods(String classAttr, String queryClass, boolean expected) {
    Element el = createElementWithClass(classAttr);
    String expectation = expected ? "to contain" : "NOT to contain";
    assertEquals(expected,
        el.hasClass(queryClass),
        String.format("Expected element with class attribute \"%s\" %s class \"%s\"",
            classAttr, expectation, queryClass));
}

