private OutputSettings createAsciiExtendedSettings() {
    return new OutputSettings()
            .charset("ascii")
            .escapeMode(extended);
}

@Test
public void caseSensitive_Escape() {
    String unescaped = "Ü ü & &";
    String actual = Entities.escape(unescaped, createAsciiExtendedSettings());
    assertEquals(
            "Escaping non-ASCII characters should produce ASCII entities",
            "&Uuml; &uuml; &amp; &amp;",
            actual);
}

@Test
public void caseSensitive_Unescape() {
    String escaped = "&Uuml; &uuml; &amp; &AMP";
    String actual = Entities.unescape(escaped);
    assertEquals(
            "Unescaping entities should return original characters",
            "Ü ü & &",
            actual);
}

