@Test
public void xhtml() {
    final int AMP_CODEPOINT = 38;
    final int GT_CODEPOINT = 62;
    final int LT_CODEPOINT = 60;
    final int QUOT_CODEPOINT = 34;

    assertEquals("Codepoint for entity 'amp' should be 38", AMP_CODEPOINT, xhtml.codepointForName("amp"));
    assertEquals("Codepoint for entity 'gt' should be 62", GT_CODEPOINT, xhtml.codepointForName("gt"));
    assertEquals("Codepoint for entity 'lt' should be 60", LT_CODEPOINT, xhtml.codepointForName("lt"));
    assertEquals("Codepoint for entity 'quot' should be 34", QUOT_CODEPOINT, xhtml.codepointForName("quot"));

    assertEquals("Entity name for codepoint 38 should be 'amp'", "amp", xhtml.nameForCodepoint(AMP_CODEPOINT));
    assertEquals("Entity name for codepoint 62 should be 'gt'", "gt", xhtml.nameForCodepoint(GT_CODEPOINT));
    assertEquals("Entity name for codepoint 60 should be 'lt'", "lt", xhtml.nameForCodepoint(LT_CODEPOINT));
    assertEquals("Entity name for codepoint 34 should be 'quot'", "quot", xhtml.nameForCodepoint(QUOT_CODEPOINT));
}

